// GItS LOCAL ADDITION - not upstream STS2MCP.
//
// EB-771: THE DECISION BEHIND `skip_act`, WITH NO GAME TYPE IN IT.
//
// WHY THIS FILE IS SEPARATE FROM `GitsDebugState.cs`, and it is
// `gits/GitsForceEvent.cs`'s reason word for word: the op is one decision --
// "is this run allowed to leave its act right now, and which act does it land
// in" -- and `klee-mod/KleeTests` can compile THIS file and exercise that
// decision headlessly, exactly as it already compiles `GitsPort.cs`,
// `GitsModalTargeting.cs` and `GitsForceEvent.cs`. The half that needs
// `RunManager` (reading the run and making the game's own call) stays in
// `GitsDebugState.cs`, where it is four statements over the answer this file
// computes. One file, no fork.
//
// THE NATIVE CALL, AND WHY IT IS THE BOSS-REWARDS BUTTON'S OWN.
//
//   MegaCrit.Sts2.Core.Nodes.Screens.NRewardsScreen.OnProceedButtonPressed
//     -- on a terminal BOSS rewards screen --
//     -> RunManager.Instance.ActChangeSynchronizer.SetLocalPlayerReady()
//     -> ActionQueueSynchronizer.RequestEnqueue(VoteToMoveToNextActAction)
//     -> ActChangeSynchronizer.OnPlayerReady -> MoveToNextAct()
//          _runState.ActFloor++;
//          TaskHelper.RunSafely(RunManager.Instance.EnterNextAct());
//     -> RunManager.EnterNextAct -> EnterAct(CurrentActIndex + 1)
//          -> FadeOut, ClearScreens, ExitCurrentRooms,
//             SetActInternal(index)  [CurrentActIndex, ClearVisitedMapCoords,
//                                     Odds.UnknownMapPoint.ResetToBase,
//                                     PreloadManager.LoadActAssets(State.Act),
//                                     GenerateMap(), music, rich presence]
//          -> EnterRoomInternal(new MapRoom()), ActEntered, FadeIn,
//             Hook.AfterActEntered
//
// So `skip_act` does not fake a boss clear, does not construct an act, does
// not touch `CurrentActIndex` by hand and does not invent a map. It presses
// the button the player presses after the boss, one floor early. Everything
// downstream -- the act transition screen, the asset preload, the map roll,
// the music swap, the save -- is the game's, in the game's order.
//
// THE ACT IT LANDS IN IS THE ONE THE EMBARK ALREADY ROLLED. `RunState.Acts` is
// built ONCE, at run start, by `ActModel.GetRandomList` walking
// `ModelDb.ActsByIndex` and taking one `rng.NextItem` per index; with the
// Teyvat arm on, that bucket is the dressing pair the
// `ModelDb.get_Acts` postfix published (Natlan/Inazuma at the Hive's index,
// Fontaine/Sumeru at Glory's). `Acts[CurrentActIndex + 1]` is therefore the
// DRESSED face this seed chose, not a second roll and not a default -- which
// is the whole reason the op is worth having: it reaches acts 2 and 3 exactly
// as a real transition would have reached them.
//
// WHAT IT COSTS THE RUN'S RNG, STATED RATHER THAN HIDDEN, because a debug op
// that claimed to be free would be the more expensive mistake. `force_next_event`
// consumes no rng and says so. THIS OP IS NOT THAT OP. It skips the rest of
// the act's floors, so every roll those floors would have taken -- room types,
// encounters, rewards, card offers, the act's own boss fight -- is a roll that
// never happens, and each act-scoped stream is read from a different position
// from then on. The acts themselves and their room sets were generated up
// front (`RunManager.GenerateRooms`) and are untouched; the MAP for the new act
// is generated by `GenerateMap` at the moment of the transition, which is when
// the game would have generated it anyway. Nothing after a `skip_act` is
// comparable to anything, including this run's own earlier floors. The route's
// guardrail says so on every answer and this file does not soften it.
//
// NO ACT-4 PATH, AND THAT IS A REFUSAL RATHER THAN AN OMISSION.
// `RunManager.EnterNextAct` has a second branch: standing on the LAST act it
// does not advance at all, it enters `TheArchitect`'s event room (or throws, in
// a victory room). EB-771 is about reaching the dressed acts 2 and 3; the
// Abyss is reserved as the act-4 face and is not built. So this file refuses at
// the last act by name instead of letting the native call quietly do something
// else.
//
// WHY THE REFUSALS ARE HERE AND NOT SPREAD THROUGH THE ROUTE. Each one is a
// state in which `SetLocalPlayerReady` would either be ignored by the game or
// would land somewhere the caller did not ask for, and a debug op that answers
// `ok` and does something else is the failure every refusal on this route
// exists to stop.

using System;
using System.Collections.Generic;

namespace STS2_MCP;

/// <summary>EB-771. Whether a run may leave its act right now, and which act
/// it lands in -- the whole decision `skip_act` makes.</summary>
public static class GitsSkipAct
{
    /// <summary>The answer. `Allowed` false carries the sentence the route
    /// refuses with, and nothing is written.</summary>
    public readonly struct Decision
    {
        public Decision(bool allowed, string refusal, int fromIndex,
                        int toIndex, int actCount, string fromAct, string toAct)
        {
            Allowed = allowed;
            Refusal = refusal;
            FromIndex = fromIndex;
            ToIndex = toIndex;
            ActCount = actCount;
            FromAct = fromAct;
            ToAct = toAct;
        }

        /// <summary>Whether the op may make the native call.</summary>
        public bool Allowed { get; }

        /// <summary>Why not, in the caller's words, or the empty string.</summary>
        public string Refusal { get; }

        /// <summary>The act index the run stands in, or -1.</summary>
        public int FromIndex { get; }

        /// <summary>The act index it would land in, or -1. Always
        /// <see cref="FromIndex"/> + 1: this op steps ONE act and there is no
        /// jump-to-index form, because an index the run's own transition never
        /// produces is a run shape nothing else in the game makes.</summary>
        public int ToIndex { get; }

        /// <summary>How many acts this run holds.</summary>
        public int ActCount { get; }

        /// <summary>The act id the run stands in, as the run spells it.</summary>
        public string FromAct { get; }

        /// <summary>The act id it would land in -- the DRESSED face this
        /// seed's act roll already chose, read out of the run's own list and
        /// never rolled again here.</summary>
        public string ToAct { get; }
    }

    /// <summary>The one refusal a caller is most likely to meet, spelled once
    /// so the route and the tests cannot drift apart.</summary>
    public const string LastActRefusal =
        "This run is already in its last act, and skip_act adds no act-4 "
        + "path. RunManager.EnterNextAct would not advance from here -- it "
        + "opens The Architect's room instead -- so the op refuses rather "
        + "than landing the run somewhere it was not asked to go.";

    /// <summary>Decide, from the facts the route reads off the live run.
    ///
    /// `actIds` is `RunState.Acts` in order, `currentActIndex` is
    /// `RunState.CurrentActIndex`, `inCombat` is
    /// `CombatManager.Instance.IsInProgress`, `inVictoryRoom` is the current
    /// room's `IsVictoryRoom`, and `roomDepth` is `RunState.CurrentRoomCount`
    /// -- greater than one means the run is inside a sub-room (an event's own
    /// fight, say) with a room still stacked beneath it.</summary>
    public static Decision Decide(IReadOnlyList<string> actIds,
                                  int currentActIndex, bool inCombat,
                                  bool inVictoryRoom, int roomDepth)
    {
        var ids = actIds ?? Array.Empty<string>();
        var count = ids.Count;

        if (count == 0)
            return Refuse("This run reports no acts at all, so there is no "
                          + "next act to enter.", -1, 0, "", "");

        if (currentActIndex < 0 || currentActIndex >= count)
            return Refuse(
                $"The run's CurrentActIndex is {currentActIndex}, which is "
                + $"outside its {count}-act list. Nothing here can name a "
                + "next act from that.", currentActIndex, count, "", "");

        var fromAct = ids[currentActIndex] ?? "";

        // COMBAT FIRST, because it is the state a caller is most likely to be
        // in by accident and the most expensive to get wrong: the transition
        // tears the room stack down underneath a live combat state, and the
        // combat's own synchronizer would still be running.
        if (inCombat)
            return Refuse(
                "A combat is in progress. skip_act ends the ACT at the next "
                + "map step; run mid-combat it would tear the room stack down "
                + "under a live combat state. Finish or flee the fight and "
                + "call it from the map.",
                currentActIndex, count, fromAct, "");

        if (roomDepth > 1)
            return Refuse(
                $"The run is {roomDepth} rooms deep -- it is inside a "
                + "sub-room (an event's own fight is the usual one) with a "
                + "room still stacked beneath it. Leave the sub-room first; "
                + "an act transition from here would exit rooms the run "
                + "still expects to return to.",
                currentActIndex, count, fromAct, "");

        if (inVictoryRoom)
            return Refuse(
                "The run is standing in its victory room, where the game "
                + "calls WinRun and not EnterNextAct. There is no next act "
                + "from here.", currentActIndex, count, fromAct, "");

        if (currentActIndex >= count - 1)
            return Refuse(LastActRefusal, currentActIndex, count, fromAct, "");

        var toIndex = currentActIndex + 1;
        return new Decision(true, "", currentActIndex, toIndex, count,
                            fromAct, ids[toIndex] ?? "");
    }

    private static Decision Refuse(string why, int fromIndex, int count,
                                   string fromAct, string toAct)
        => new Decision(false, why, fromIndex, -1, count, fromAct, toAct);
}
